import{_ as t,o as s,c as n,l as i,t as r,N as o}from"./chunks/framework.Gjrf2Eoj.js";const b=JSON.parse('{"title":"ldconfig | x-cmd man (man8) | configure dynamic linker run-time bindings","titleTemplate":false,"description":"x-cmd man (man8 Manual Page) | ldconfig - configure dynamic linker run-time bindings","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ldconfig | x-cmd man (man8) | configure dynamic linker run-time bindings"}],["meta",{"name":"og:description","content":"x-cmd man (man8 Manual Page) | ldconfig - configure dynamic linker run-time bindings"}]]},"headers":[],"params":{"isMan":true,"man":"ldconfig","category":"man8","desc":"configure dynamic linker run-time bindings"},"relativePath":"man8/ldconfig.md","filePath":"man8/ldconfig.md"}'),a={name:"man8/ldconfig.md"},d={class:"visually-hidden"},l=o('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ldconfig - configure dynamic linker run-time bindings</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>/sbin/ldconfig</strong> [<strong>-nNvVX</strong>] [<strong>-C ** <em>cache</em>] [</strong>-f ** <em>conf</em>] [<strong>-r ** <em>root</em>] <em>directory</em> . . . <strong>/sbin/ldconfig</strong> <strong>-l</strong> [</strong>-v**] <em>library</em> . . . <strong>/sbin/ldconfig</strong> <strong>-p</strong></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p><strong>ldconfig</strong> creates the necessary links and cache to the most recent shared libraries found in the directories specified on the command line, in the file <em>/etc/ld.so.conf</em>, and in the trusted directories, <em>/lib</em> and <em>/usr/lib</em>. On some 64-bit architectures such as x86-64, <em>/lib</em> and <em>/usr/lib</em> are the trusted directories for 32-bit libraries, while <em>/lib64</em> and <em>/usr/lib64</em> are used for 64-bit libraries.</p><p>The cache is used by the run-time linker, <em>ld.so</em> or <em>ld-linux.so</em>. <strong>ldconfig</strong> checks the header and filenames of the libraries it encounters when determining which versions should have their links updated. <strong>ldconfig</strong> should normally be run by the superuser as it may require write permission on some root owned directories and files.</p><p><strong>ldconfig</strong> will look only at files that are named <em>lib*.so*</em> (for regular shared objects) or <em>ld-*.so*</em> (for the dynamic loader itself). Other files will be ignored. Also, <strong>ldconfig</strong> expects a certain pattern to how the symbolic links are set up, like this example, where the middle file (<strong>libfoo.so.1</strong> here) is the SONAME for the library:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">libfoo.so</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> -</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libfoo.so.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> -</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libfoo.so.1.12</span></span></code></pre></div><p>Failure to follow this pattern may result in compatibility issues after an upgrade.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><dl><dt><strong>--format=</strong> <em>fmt</em> <br> <strong>-c</strong> <em>fmt</em></dt><dd>(Since glibc 2.2) Use cache format <em>fmt</em>, which is one of <strong>old</strong>, <strong>new</strong>, or <strong>compat</strong>. Since glibc 2.32, the default is <strong>new</strong>. Before that, it was <strong>compat</strong>.</dd><dt><strong>-C</strong> <em>cache</em></dt><dd>Use <em>cache</em> instead of <em>/etc/ld.so.cache</em>.</dd><dt><strong>-f</strong> <em>conf</em></dt><dd>Use <em>conf</em> instead of <em>/etc/ld.so.conf</em>.</dd><dt><strong>--ignore-aux-cache</strong> <br> <strong>-i</strong></dt><dd>(Since glibc 2.7) Ignore auxiliary cache file.</dd><dt><strong>-l</strong></dt><dd>(Since glibc 2.2) Interpret each operand as a library name and configure its links. Intended for use only by experts.</dd><dt><strong>-n</strong></dt><dd>Process only the directories specified on the command line; don&#39;t process the trusted directories, nor those specified in <em>/etc/ld.so.conf</em>. Implies <strong>-N</strong>.</dd><dt><strong>-N</strong></dt><dd>Don&#39;t rebuild the cache. Unless <strong>-X</strong> is also specified, links are still updated.</dd><dt><strong>--print-cache</strong> <br> <strong>-p</strong></dt><dd>Print the lists of directories and candidate libraries stored in the current cache.</dd><dt><strong>-r</strong> <em>root</em></dt><dd>Change to and use <em>root</em> as the root directory.</dd><dt><strong>--verbose</strong> <br> <strong>-v</strong></dt><dd>Verbose mode. Print current version number, the name of each directory as it is scanned, and any links that are created. Overrides quiet mode.</dd><dt><strong>--version</strong> <br> <strong>-V</strong></dt><dd>Print program version.</dd><dt><strong>-X</strong></dt><dd>Don&#39;t update links. Unless <strong>-N</strong> is also specified, the cache is still rebuilt.</dd></dl><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><dl><dt><em>/lib/ld.so</em></dt><dd>is the run-time linker/loader.</dd><dt><em>/etc/ld.so.conf</em></dt><dd>contains a list of directories, one per line, in which to search for libraries.</dd><dt><em>/etc/ld.so.cache</em></dt><dd>contains an ordered list of libraries found in the directories specified in <em>/etc/ld.so.conf</em>, as well as those found in the trusted directories.</dd></dl><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>ldd</strong>(1), <strong>ld.so</strong>(8)</p>',16);function c(e,m,g,h,f,p){return s(),n("div",null,[i("h1",d,r(e.$params.man),1),l])}const k=t(a,[["render",c]]);export{b as __pageData,k as default};
